"""Render projects with different answers and check what comes out."""

import hashlib
import re
from pathlib import Path
from typing import Callable

import pytest
import yaml
from cookiecutter.exceptions import FailedHookException

SNAPSHOT_HEADER = (
    "# machine-owned: generated by dbx-platform-registry; do not edit; change it through the registry. content-sha256="
)
EXAMPLE_IDENTITY = re.compile(r"example_claims|example-claims|EXAMPLECLAIMS|exampleclaims|Example Claims|dbx-example")
ANSWERS = {
    "project_id": "claims_fraud",
    "squad_title": "Claims Fraud Squad",
    "domain": "claims__litigation",
}
Render = Callable[..., Path]


def text_files(project: Path):
    """Yield every text file of a rendered project, skipping git data and the framework checkout."""
    for path in project.rglob("*"):
        if (
            path.is_file()
            and not {".git", "lakeflow_framework"} & set(path.parts)
            and b"\0" not in path.read_bytes()[:4096]
        ):
            yield path


def snapshot_problem(path: Path) -> str | None:
    """Return what is wrong with a `_platform` snapshot's hash header, or None when it is intact."""
    first, _, body = path.read_text(encoding="utf-8").partition("\n")
    if not first.startswith(SNAPSHOT_HEADER):
        return "no header"
    return (
        None
        if first.removeprefix(SNAPSHOT_HEADER) == hashlib.sha256(body.encode("utf-8")).hexdigest()
        else "stale hash"
    )


def test__default_answers_give_the_example_squad_with_all_three_bundles(render: Render):
    """With the defaults the output is the example project: a git repository, three bundles, project example_claims."""
    project = render()
    assert project.name == "dbx-example-claims"
    assert (project / ".git").is_dir()
    assert sorted(path.name for path in (project / "bundles").iterdir()) == ["aiops", "dataops", "mlops"]
    repo = yaml.safe_load((project / "metadata/_platform/repo.yaml").read_text(encoding="utf-8").split("\n", 1)[1])
    assert (repo["project_id"], repo["kind"], repo["domain"]) == ("example_claims", "project", "claims")


def test__the_answers_replace_the_example_squad_in_every_file(render: Render):
    """No file keeps the example project's id, GitHub team, AD group token, title or repository name."""
    project = render(**ANSWERS)
    assert project.name == "dbx-claims-fraud"
    leftovers = {
        str(path.relative_to(project))
        for path in text_files(project)
        if EXAMPLE_IDENTITY.search(path.read_text("utf-8"))
    }
    assert leftovers == set()
    assert not list(project.rglob("*example_claims*"))
    assert (project / "templates/registry-repo/projects/claims_fraud.yaml").is_file()


def test__the_answers_land_in_the_squad_snapshots_and_the_registry_example(render: Render):
    """repo.yaml, teams.yaml and the scaffold's registration agree on id, title, domain and the derived names."""
    project = render(**ANSWERS)
    platform = project / "metadata/_platform"
    repo = yaml.safe_load((platform / "repo.yaml").read_text(encoding="utf-8"))
    team = yaml.safe_load((platform / "teams.yaml").read_text(encoding="utf-8"))["teams"][0]
    registration = yaml.safe_load(
        (project / "templates/registry-repo/projects/claims_fraud.yaml").read_text(encoding="utf-8")
    )
    assert (repo["project_id"], repo["domain"], repo["project"]["title"]) == (
        "claims_fraud",
        "claims__litigation",
        "Claims Fraud Squad",
    )
    assert (team["name"], team["github_team"], team["domain"]) == (
        "claims_fraud_squad",
        "claims-fraud",
        "claims__litigation",
    )
    assert team["groups"]["developers"] == "AAD-DBX-CLAIMSFRAUD-DEV"
    assert registration["repo"] == {"name": "dbx-claims-fraud"}
    assert registration["domain"] == "claims__litigation"


@pytest.mark.parametrize("answers", [{}, ANSWERS, {**ANSWERS, "kind": "domain", "include_examples": "no"}])
def test__every_snapshot_has_a_valid_hash_header_after_the_rewrite(render: Render, answers: dict):
    """A hand edit is detected by the hash header, so the rewritten snapshots must carry a correct one."""
    platform = render(**answers) / "metadata/_platform"
    problems = {
        name: snapshot_problem(platform / name) for name in ("repo.yaml", "teams.yaml", "domains.yaml", "glossary.ttl")
    }
    assert problems == {name: None for name in problems}


def test__the_distribution_name_follows_the_repository_name_but_the_published_library_name_does_not(render: Render):
    """Jobs and pyproject name this repo's own wheel; the registry scaffold installs the published library."""
    project = render(**ANSWERS)
    assert 'name = "dbx-claims-fraud"' in (project / "pyproject.toml").read_text(encoding="utf-8")
    assert "package_name: dbx-claims-fraud" in (project / "bundles/dataops/resources/dataops.jobs.yml").read_text(
        encoding="utf-8"
    )
    assert "cookie-cutter-dbx==" in (
        project / "templates/registry-repo/.github/workflows/registry-validate.yml"
    ).read_text(encoding="utf-8")


def test__without_examples_only_the_checks_every_bundle_needs_remain(render: Render):
    """include_examples=no removes the example bundles and the tests written for them, and the rest still parses."""
    project = render(**ANSWERS, kind="domain", include_examples="no")
    assert [path.name for path in (project / "bundles").iterdir()] == [".gitkeep"]
    assert sorted(path.name for path in (project / "tests/bundles").iterdir() if path.suffix == ".py") == [
        "__init__.py",
        "test_bundles.py",
        "test_stage_framework.py",
    ]
    assert not (project / "tests/unit_tests/metastore/test_publish_real_repo.py").exists()
    guard = (project / "tests/bundles/test_bundles.py").read_text(encoding="utf-8")
    assert "test__there_is_at_least_one_bundle" not in guard
    compile(guard, "test_bundles.py", "exec")
    assert yaml.safe_load((project / "metadata/_platform/repo.yaml").read_text(encoding="utf-8"))["kind"] == "domain"


def test__a_framework_that_cannot_be_added_is_reported_and_the_project_is_still_created(render: Render, capfd):
    """Offline generation works; the hook says what to run, instead of leaving a silently broken project."""
    project = render()
    assert not (project / "framework/lakeflow_framework/src").exists()
    assert "bash scripts/add_framework.sh" in capfd.readouterr().err


@pytest.mark.parametrize(
    "answers",
    [
        {"project_id": "Claims-Fraud"},
        {"project_id": "ab"},
        {"repo_name": "claims-fraud"},
        {"squad_title": 'Bad "title"'},
        {"domain": "Claims"},
        {"kind": "domain"},
    ],
    ids=["id-chars", "id-short", "repo-prefix", "title-quote", "domain-case", "domain-kind-with-examples"],
)
def test__bad_answers_are_rejected_before_anything_is_generated(render: Render, answers: dict, tmp_path: Path):
    """Each answer that the registry would refuse is refused here, and no project is left behind."""
    with pytest.raises(FailedHookException):
        render(**answers)
    assert not any((tmp_path / "out").glob("*"))


def test__an_unknown_domain_is_rejected_with_a_suggestion(render: Render, capfd, tmp_path: Path):
    """The taxonomy's own message, including the 'did you mean', reaches the person generating the project."""
    with pytest.raises(FailedHookException):
        render(domain="claims__litigaton")
    assert "did you mean" in capfd.readouterr().err
    assert not any((tmp_path / "out").glob("*"))
